        for (auto inter : intervals) {
            vector<int> cur = inter;
            vector<vector<int>> nxt;
            for (auto m : merged) {
                if (max(cur[0], m[0]) <= min(cur[1], m[1])) {
                    cur = {min(cur[0], m[0]), max(cur[1], m[1])};
                } else {
                    nxt.push_back(m);
                }
            }
            nxt.push_back(cur);
            merged = move(nxt);
        }
        return merged;
    }
};

