class Solution {
    public int[][] merge(int[][] intervals) {
        List<int[]> merged = new ArrayList<>();
        for (int[] inter : intervals) {
            int[] cur = new int[]{inter[0], inter[1]};
            List<int[]> nxt = new ArrayList<>();
            for (int[] m : merged) {
                if (Math.max(cur[0], m[0]) <= Math.min(cur[1], m[1])) {
                    cur = new int[]{Math.min(cur[0], m[0]), Math.max(cur[1], m[1])};
                } else {
                    nxt.add(m);
                }
            }
            nxt.add(cur);
            merged = nxt;
        }
        return merged.toArray(new int[merged.size()][]);
    }
}

